local({
  bp <- as.numeric(birthplace)
  born <- case_when(
    bp == 1 ~ "Yes",
    bp %in% 2:6 ~ "No",
    bp == 7 & grepl("singapore", tolower(birthplacet)) ~ NA_character_,
    bp == 7 ~ "No"
  )
  coalesce(carry_within(born, sn, order = as.numeric(wave)), "Unknown")
})

local({
  hours <- as.numeric(hb2)
  how_long <- as.numeric(hb3_0)
  when <- as.numeric(hb6_0)
  case_when(
    hours %in% 2:4 | how_long %in% 2:4 | when %in% 2:4 ~ "TRUE",
    hours %in% 1 | how_long %in% 1 | when %in% 1 ~ "FALSE"
  )
})

local({
  items <- cbind(as.numeric(ac1), as.numeric(ac2), as.numeric(ac3), as.numeric(ac4), as.numeric(ac5))
  case_when(rowSums(items == 1, na.rm = TRUE) > 0 ~ "TRUE", rowSums(!is.na(items)) > 0 ~ "FALSE")
})

local({
  items <- cbind(as.numeric(dc41), as.numeric(dc42), as.numeric(dc43))
  case_when(rowSums(items >= 2, na.rm = TRUE) > 0 ~ "TRUE", rowSums(!is.na(items)) > 0 ~ "FALSE")
})

