local({
  mother <- as.numeric(ba39)
  father <- as.numeric(ba40)
  if_else(is.na(mother) & is.na(father), NA_real_, rowMeans(cbind(mother, father), na.rm = TRUE))
})

local({
  height <- coalesce(
    if_else(trimws(height.q) %in% "180+", 180, suppressWarnings(as.numeric(height.q))),
    as.numeric(height)
  )
  weight <- coalesce(suppressWarnings(as.numeric(weight.q)), as.numeric(weight))
  if_else(height > 0 & weight > 0, weight / (height / 100)^2, NA_real_)
})
